/**
 * Backend-first dataset pipeline (Part 1 of the improvement plan).
 *
 * Source of truth (hand-edited, tracked):
 *   backend/data/commands/<slug>.json   one file per entry, named exactly the slug
 *   backend/data/commands-order.json    documentation order (aggregate + index preserve it)
 *   backend/data/categories.json        Linux category metadata
 *   backend/data/domains.json           CTF domain metadata
 *
 * Generated by this script (tracked; must stay in sync — the audit checks):
 *   backend/data/commands.json          {categories, domains, commands, needsHumanReview}
 *   backend/data/commands-index.json    {categories, domains, counts, commands: light[]}
 *
 * The light index carries {slug, name, summary, tags, category, section} per
 * entry — navigation/search metadata only, never syntax/options/examples
 * content. Command docs are served per slug by GET /api/commands/<slug>.
 *
 * Any structural violation exits non-zero; this script never silently rewrites
 * documentation content.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const dataDir = path.join(root, 'backend', 'data');
const perSlugDir = path.join(dataDir, 'commands');
const orderPath = path.join(dataDir, 'commands-order.json');
const categoriesPath = path.join(dataDir, 'categories.json');
const domainsPath = path.join(dataDir, 'domains.json');
const aggregatePath = path.join(dataDir, 'commands.json');
const indexPath = path.join(dataDir, 'commands-index.json');

const problems = [];
const fail = (rule, detail) => problems.push(`${rule}: ${detail}`);

// ------------------------------------------------------------ load sources
const files = fs.readdirSync(perSlugDir).filter((name) => name.endsWith('.json')).sort();
const entries = new Map();

for (const file of files) {
  const stem = file.slice(0, -5);
  const raw = fs.readFileSync(path.join(perSlugDir, file), 'utf8');
  let entry;
  try {
    entry = JSON.parse(raw);
  } catch (err) {
    fail('parse', `${file}: ${err.message}`);
    continue;
  }
  if (entry.slug !== stem) {
    fail('slug', `${file}: slug field '${entry.slug}' != file stem '${stem}'`);
  }
  const canonical = JSON.stringify(entry, null, 2) + '\n';
  if (raw !== canonical) {
    fail('formatting', `${file}: not canonical (JSON.stringify(entry, null, 2) + newline)`);
  }
  entries.set(stem, entry);
}

const { order } = JSON.parse(fs.readFileSync(orderPath, 'utf8'));
const categories = JSON.parse(fs.readFileSync(categoriesPath, 'utf8'));
const domains = JSON.parse(fs.readFileSync(domainsPath, 'utf8'));

const canonicalMeta = (raw) => JSON.stringify(JSON.parse(raw), null, 2) + '\n';
if (fs.readFileSync(categoriesPath, 'utf8') !== canonicalMeta(fs.readFileSync(categoriesPath, 'utf8'))) fail('formatting', 'categories.json not canonical');
if (fs.readFileSync(domainsPath, 'utf8') !== canonicalMeta(fs.readFileSync(domainsPath, 'utf8'))) fail('formatting', 'domains.json not canonical');

for (const slug of order) {
  if (!entries.has(slug)) fail('order', `commands-order.json lists '${slug}' but backend/data/commands/${slug}.json is missing`);
}
for (const slug of entries.keys()) {
  if (!order.includes(slug)) fail('order', `'${slug}.json' exists but is missing from commands-order.json`);
}

// ------------------------------------------------------------- structural rules
const catIds = new Set(categories.map((c) => c.id));
const domIds = new Set(domains.map((d) => d.id));

const commands = order.map((slug) => entries.get(slug)).filter(Boolean);
const slugs = new Set(commands.map((c) => c.slug));
if (new Set(order).size !== order.length) fail('order', 'commands-order.json contains duplicate slugs');

for (const command of commands) {
  if (command.section === 'linux' && !catIds.has(command.category)) {
    fail('category', `${command.slug}: unknown linux category '${command.category}'`);
  } else if (command.section === 'ctf' && !domIds.has(command.category)) {
    fail('category', `${command.slug}: unknown ctf domain '${command.category}'`);
  } else if (command.section !== 'linux' && command.section !== 'ctf') {
    fail('section', `${command.slug}: unknown section '${command.section}'`);
  }
  if (!Array.isArray(command.related)) fail('shape', `${command.slug}: 'related' must be an array`);
  if (!Array.isArray(command.options)) fail('shape', `${command.slug}: 'options' must be an array`);
  if (!Array.isArray(command.examples)) fail('shape', `${command.slug}: 'examples' must be an array`);
  if (!Array.isArray(command.useCases)) fail('shape', `${command.slug}: 'useCases' must be an array`);
  if (!Array.isArray(command.tags)) fail('shape', `${command.slug}: 'tags' must be an array`);
  for (const ref of command.related || []) {
    if (!slugs.has(ref)) fail('related', `${command.slug}: related references missing slug '${ref}'`);
    if (ref === command.slug) fail('related', `${command.slug}: related references itself`);
  }
}

// The thin-docs queue, exactly as defined by qa/dataset_audit.py rule (4).
const needsHumanReview = commands
  .filter((c) => (c.examples || []).length < 3 || !(c.options || []).length
    || !(c.useCases || []).length || !(c.tags || []).length)
  .map((c) => c.slug);

if (problems.length > 0) {
  console.error(`dataset validation failed (${problems.length} problems):`);
  for (const problem of problems) console.error(`  - ${problem}`);
  process.exitCode = 1;
} else {
  fs.writeFileSync(aggregatePath, JSON.stringify({ categories, domains, commands, needsHumanReview }, null, 2) + '\n', 'utf8');

  const counts = {};
  for (const command of commands) counts[command.category] = (counts[command.category] || 0) + 1;
  const lights = commands.map((c) => ({
    slug: c.slug,
    name: c.name,
    summary: c.summary,
    tags: c.tags,
    category: c.category,
    section: c.section,
  }));
  fs.writeFileSync(indexPath, JSON.stringify({ categories, domains, counts, commands: lights }, null, 2) + '\n', 'utf8');

  console.log(`dataset pipeline OK: ${commands.length} entries -> commands.json + commands-index.json (${needsHumanReview.length} pending review)`);
}
